 const [adminTab,setAdminTab]=useState('expeditions'),[rows,setRows]=useState<Row[]>([]),[requests,setRequests]=useState<Row[]>([]),[audit,setAudit]=useState<Row[]>([]),[loading,setLoading]=useState(false),[filter,setFilter]=useState(''),[statusFilter,setStatusFilter]=useState('Tous'),[detail,setDetail]=useState<Row|null>(null),[create,setCreate]=useState(false),[eventModal,setEventModal]=useState(false),[etaModal,setEtaModal]=useState(false),[privateLink,setPrivateLink]=useState(''),[adminError,setAdminError]=useState(''),[adminLogin,setAdminLogin]=useState(false),[invoiceModal,setInvoiceModal]=useState(false),[noticeModal,setNoticeModal]=useState(false),[clientNotices,setClientNotices]=useState(false),[editModal,setEditModal]=useState(false),[detailsEditor,setDetailsEditor]=useState(false),[rectify,setRectify]=useState<Row|null>(null),[eventEdit,setEventEdit]=useState<Row|null>(null);
