 {view==='admin'&&<div className="dashboard wrap"><div className="dash-header"><div><p className="eyebrow">{tr("VOTRE ESPACE DE GESTION")}</p><h1>{tr("Tout votre suivi.")}<br/><em>{tr("Au même endroit.")}</em></h1><p className="muted">{tr("Bienvenue")}{displayName?', '+displayName.split('@')[0]:''}.</p></div>{signedIn&&<div className="admin-top-actions"><button className="btn secondary" onClick={async()=>{try{await api('admin-logout',{});setSignedIn(false);setTracking(null);setAccess('');setPrivateLink('');setDetail(null);setRows([]);setRequests([]);setAudit([]);navigate('home');notify('Gestion déconnectée.');}catch(e:any){notify(e.message);}}}>{tr("Fermer la gestion")}</button><button className="btn secondary" onClick={async()=>{try{const d=await api('export');const blob=new Blob([JSON.stringify(d,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='transworld-delivery-export.json';a.click();URL.revokeObjectURL(url);}catch(e:any){notify(e.message);}}}>{tr("Exporter les données")}</button><button className="btn primary" onClick={()=>setCreate(true)}><Plus size={19}/> {tr("Nouvelle expédition")}</button></div>}</div>{!signedIn?<section className="panel empty"><Lock/><h2>{tr("Un espace de gestion sécurisé")}</h2><p>{tr("Connectez-vous pour créer et gérer vos dossiers.")}</p><button className="btn primary" onClick={()=>setAdminLogin(true)}>{tr("Se connecter")}</button></section>:<><div className="stats-grid">{[{n:rows.length,label:'Expéditions',icon:Package},{n:rows.filter(r=>!['Livré','Annulé','Retourné'].includes(r.status)).length,label:'En cours',icon:Ship},{n:rows.filter(r=>r.status==='Livré').length,label:'Livrées',icon:CheckCircle2},{n:requests.length,label:'Demandes',icon:Inbox},{n:rows.reduce((n,r)=>n+(Number(r.proof_count)||0),0),label:'Preuves à vérifier',icon:FileText}].map(s=><div className="stat" key={s.label}><div><span>{tr(s.label)}</span><strong>{s.n}</strong></div><s.icon size={24}/></div>)}</div><div className="dash-nav"><div>{[['expeditions','Expéditions',Package],['demandes','Demandes',Inbox],['journal','Journal',History],['pays','Pays',Globe],['services','Prestations',Box],['identite','Entreprise',FileCheck],['sauvegarde','Sauvegarde',Download],['reglages','Réglages',Globe]].map(([id,label,Icon]:any)=><button key={id} className={adminTab===id?'active':''} onClick={()=>setAdminTab(id)}><Icon size={17}/>{tr(label)}</button>)}</div><button className="icon-btn" aria-label={tr("Actualiser les dossiers")} onClick={loadAdmin} disabled={loading}><RefreshCw className={loading?'spin':''} size={18}/></button></div>{adminError&&<p className="form-error" role="alert">{adminError}</p>}{adminTab==='expeditions'&&<section className="panel records-panel"><div className="records-controls"><div className="search-field"><Search size={17}/><input aria-label={tr("Rechercher un dossier")} placeholder={tr("Référence, client, marchandise…")} value={filter} onChange={e=>setFilter(e.target.value)}/></div><select aria-label={tr("Filtrer par statut")} value={statusFilter} onChange={e=>setStatusFilter(e.target.value)}>{['Tous',...stages,'Annulé','Retourné'].map(s=><option key={s} value={s}>{tr(s)}</option>)}</select></div>{loading&&rows.length===0?<div className="empty"><RefreshCw className="spin"/><p>{tr("Chargement des dossiers…")}</p></div>:filtered.length?<div className="records">{filtered.map(r=><button className="record" key={r.id} onClick={()=>openDetail(r.id)}><span className="record-icon">{r.category==='Véhicule'?<Car/>:r.category==='Moto'?<Motorbike/>:<Package/>}</span><div className="record-main"><strong>{r.item}</strong><span>{r.client} • {r.ref}</span></div><div className="record-route">{r.origin}<ArrowRight size={14}/>{r.destination}</div><Badge status={r.proof_count?'Preuve à vérifier':r.status}/><ChevronRight size={17}/></button>)}</div>:<div className="empty"><Package size={32}/><h3>{tr(rows.length?'Aucun résultat.':'Votre première expédition commence ici.')}</h3><p>{tr(rows.length?'Essayez une autre recherche.':'Créez un dossier, ajoutez les informations confirmées et partagez le suivi.')}</p>{!rows.length&&<button className="btn primary" onClick={()=>setCreate(true)}>{tr("Créer un dossier")}<Plus size={17}/></button>}</div>}</section>}{adminTab==='demandes'&&<section className="panel records-panel">{requests.length?requests.map(r=><article className="request-row" key={r.id}><div><p className="eyebrow">{r.category} • {date(r.created)}</p><h3>{r.name}</h3><p>{r.origin} → {r.destination}</p><p>{r.contact}</p><p className="muted">{r.note}</p></div><button className="btn secondary" onClick={()=>copy(r.contact)}><Copy size={16}/> {tr("Copier le contact")}</button></article>):<div className="empty"><Inbox/><h3>{tr("Aucune demande pour le moment.")}</h3><p>{tr("Les demandes envoyées depuis le site apparaîtront ici.")}</p></div>}</section>}{adminTab==='journal'&&<section className="panel records-panel">{audit.length?audit.map((a,i)=><div className="audit-row" key={i}><History size={17}/><div><strong>{a.action}</strong><p>{a.detail}</p><small>{a.ref} • {date(a.created,true)}</small></div></div>):<div className="empty"><History/><h3>{tr("Un historique pour chaque action.")}</h3><p>{tr("Les créations, publications et documents ajoutés seront enregistrés ici.")}</p></div>}</section>}{adminTab==='pays'&&<ModelManager kind="country"/>}{adminTab==='services'&&<ModelManager kind="service"/>}{adminTab==='identite'&&<CompanyForm/>}{adminTab==='sauvegarde'&&<BackupPanel/>}{adminTab==='reglages'&&<section className="panel info-panel"><ConnectionCheck/><MapsSettings onSuccess={()=>notify('Réglages de carte enregistrés. Rouvrez le suivi pour les appliquer.')}/></section>}<p className="dash-note"><ShieldCheck size={16}/> {tr("Vos dossiers sont liés à votre compte. Aucun dossier fictif n’est enregistré.")}</p></>}</div>}
