function PaymentProof({invoiceId,reference,access,onSuccess}:{invoiceId:string,reference:string,access:string,onSuccess:()=>void}){const[error,setError]=useState(''),[busy,setBusy]=useState(false);return <form className="proof-form" onSubmit={async e=>{e.preventDefault();setBusy(true);setError('');const f=new FormData(e.currentTarget);f.set('ref',reference);f.set('access',access);try{await uploadPrivateFile(f.get('file') as File,{invoiceId,ref:reference,access});onSuccess();}catch(e:any){setError(e.message);}finally{setBusy(false);}}}><label>{tr("Transmettre une preuve de paiement")}<input type="file" name="file" accept="application/pdf,image/png,image/jpeg" required/></label><FormError error={error}/><button className="btn secondary" disabled={busy}>{tr(busy?'Transmission…':'Envoyer la preuve à l’agence')}</button></form>;}

function EditForm({detail,onSuccess}:{detail:Row,onSuccess:(r:Row)=>void}){const[error,setError]=useState(''),[busy,setBusy]=useState(false);const s=detail.shipment;return <form className="form" onSubmit={async e=>{e.preventDefault();setBusy(true);setError('');try{onSuccess(await api('shipments/'+s.id+'/update',{...Object.fromEntries(new FormData(e.currentTarget).entries()),version:s.version}));}catch(e:any){setError(e.message);}finally{setBusy(false);}}}><div className="form-grid"><Field label={tr("Nom du client")} name="client" defaultValue={s.client}/><Field label={tr("Contact")} name="contact" required={false} defaultValue={s.contact}/></div><Field label={tr("Courriel de notification")} name="email" type="email" required={false} defaultValue={s.email}/><Field label={tr("Marchandise")} name="item" required={false} defaultValue={s.item}/><div className="form-grid"><Field label={tr("Départ")} name="origin" required={false} defaultValue={s.origin}/><Field label={tr("Destination")} name="destination" required={false} defaultValue={s.destination}/></div><Field label={tr("Conteneur ou lot")} name="container" required={false} defaultValue={s.container}/><Field label={tr("Lieu de remise souhaité")} name="delivery" required={false} defaultValue={s.delivery}/><p className="tiny muted">{tr("Changer le contact ou le courriel révoque l’ancien lien privé. La correction reste dans le journal.")}</p><FormError error={error}/><button className="btn primary" disabled={busy}>{tr(busy?'Enregistrement…':'Enregistrer la correction')}</button></form>;}

function MapsSettings({onSuccess}:{onSuccess:()=>void}){const [config,setConfig]=useState<Row|null>(null),[error,setError]=useState(''),[busy,setBusy]=useState(false);useEffect(()=>{api('settings').then(setConfig).catch(e=>setError(e.message));},[]);return <><h2>{tr("Cartographie & Serveur de tuiles")}</h2><p className="muted tiny">{tr("La cartographie OpenStreetMap / Leaflet est intégrée nativement sans clé obligatoire. Vous pouvez personnaliser le serveur de tuiles (OSM, Mapbox, Carto) et son attribution.")}</p>{config&&<form className="form" onSubmit={async e=>{e.preventDefault();setBusy(true);setError('');try{await api('settings',Object.fromEntries(new FormData(e.currentTarget).entries()));onSuccess();}catch(e:any){setError(e.message);}finally{setBusy(false);}}}><Field label={tr("URL des tuiles cartographiques (vide = OpenStreetMap officiel)")} name="tile_url" required={false} defaultValue={config.tile_url||''} placeholder="https://tile.openstreetmap.org/{z}/{x}/{y}.png"/><Field label={tr("Texte d'attribution légale")} name="tile_attribution" required={false} defaultValue={config.tile_attribution||''} placeholder="&copy; OpenStreetMap contributors"/><p className="tiny muted">{tr("Politique d'utilisation : les tuiles sont chargées à la demande lors de la consultation. Tout téléchargement massif ou préchargement est proscrit.")}</p><button className="btn primary" disabled={busy}>{tr(busy?'Enregistrement…':'Enregistrer les paramètres cartographiques')}</button></form>}<FormError error={error}/><h3 className="detail-section-title">{tr("Courriels automatiques")}</h3><p className="muted tiny">{tr("L’adresse expéditrice vérifiée et la clé secrète du service de courriel doivent être configurées côté serveur. Les échecs et messages en attente sont visibles dans chaque dossier.")}</p></>;}

function Country({label,name,defaultValue}:{label:string,name:string,defaultValue?:string}){return <label>{tr(label)}<input name={name} list={name+"-countries"} defaultValue={defaultValue} placeholder={tr("Choisir ou saisir un pays")}/><datalist id={name+"-countries"}>{countries.map(c=><option key={c} value={c}/>)}</datalist></label>;}

function ServiceList({rows,shipmentId,onRefresh}:{rows:Row[],shipmentId?:string,onRefresh?:()=>void}){
 const [error,setError]=useState(''),[busy,setBusy]=useState(false);
 if(!rows.length)return null;
 const labels:Record<string,string>={awaiting_payment:'En attente de paiement validé',ready:'Paiement autorisé ou non requis — prise en charge à confirmer',confirmed:'Prise en charge confirmée',rectified:'Facture rectifiée — consulter le document associé'};
 return <section className="panel info-panel"><h3>{tr('Prestations et actions attendues')}</h3><p className="tiny muted">{tr('Ces confirmations ne remplacent pas les étapes physiques du transport.')}</p>{rows.map(t=><article className="invoice-card" key={t.id}><strong>{t.action}</strong><p>{t.number} · {tr(labels[t.state]||t.state)}</p>{t.source&&<p>{t.source}</p>}{t.confirmed_at&&<small>{date(t.confirmed_at,true)}</small>}{shipmentId&&t.state==='ready'&&<button className="btn secondary" disabled={busy} onClick={async()=>{const source=window.prompt(tr('Précisez la source de la prise en charge réellement confirmée.'));if(!source?.trim())return;setBusy(true);setError('');try{await api('shipments/'+shipmentId+'/service-confirm',{taskId:t.id,version:t.version,source});await onRefresh?.();}catch(e:any){setError(e.message);}finally{setBusy(false);}}}>{tr('Confirmer la prise en charge réelle')}</button>}</article>)}<FormError error={error}/></section>;
}

function ConnectionCheck(){
 const [busy,setBusy]=useState(false),[error,setError]=useState(''),[result,setResult]=useState<Row|null>(null);
 return <section><h2>{tr('Vérifier ma connexion Supabase')}</h2><p>{tr('Ce contrôle interroge réellement la base et vérifie que le stockage est privé. Il ne remplace pas un essai d’import de document.')}</p><button className="btn secondary" disabled={busy} onClick={async()=>{setBusy(true);setResult(null);setError('');try{setResult(await api('health'));}catch(e:any){setError(e.message);}finally{setBusy(false);}}}>{tr(busy?'Vérification…':'Tester la base et le stockage')}</button><FormError error={error}/>{result&&<p className="success" role="status">{tr(result.database&&result.privateStorage?'Base connectée et stockage privé vérifié.':'Le stockage privé reste à vérifier.')}{' '}{tr(result.emailConfigured?'Email configuré — réception à tester.':'Email non configuré ; notifications internes disponibles.')}</p>}</section>;
}

function InvoiceTotals({invoices}:{invoices:Row[]}){
 if(!invoices.length)return null;
 const sum=(key:string,paid?:boolean)=>invoices.filter(i=>paid===undefined||((i.status==='paye')===paid)).reduce((n,i)=>n+Number(i[key]||0),0);
 const amount=(paid?:boolean)=>sum('usd',paid).toFixed(2)+' USD · '+Math.round(sum('gnf',paid)).toLocaleString('fr-FR')+' GNF';
 return <div className="review"><p><span>{tr('Factures actives émises')}</span><strong>{amount()}</strong></p><p><span>{tr('Paiements validés')}</span><strong>{amount(true)}</strong></p><p><span>{tr('Solde des factures actives')}</span><strong>{amount(false)}</strong></p><small>{tr('Les documents rectifiés sont exclus de ces totaux. Le prix d’achat et les prestations encore indéterminées ne sont pas ajoutés à ce récapitulatif.')}</small></div>;
}
